-- Seed data for public.blog_posts: migrate the two hand-written
-- article pages (BlogTsChallenge, BlogHistoryOfRemix) into the
-- new block-based blog editor.
--
-- Each row uses a single custom_html block that contains the
-- fully-materialized article body. The custom_html block is
-- the intentional escape hatch (see src/data/blog/types.ts) for
-- preserving rich article-specific markup.
--
-- Idempotent: `on conflict (slug) do update` refreshes an
-- existing row so this can be re-run safely.

insert into public.blog_posts (
  slug, status, title, subtitle, description, author, tag,
  hero_image_url, hero_image_alt, og_image_url, read_minutes,
  content, published_at
) values
(
  'ts-challenge',
  'published',
  'What is the Times Square Billboard Challenge and how to participate',
  null,
  'How collectors, artists, and fans worldwide engage with limited-edition NFT.NYC art on Times Square''s biggest screens. A complete guide to the TS Challenge, T-XP, gift NFTs, and the leaderboard.',
  'NFT.NYC and OneHub team',
  'TS Challenge',
  '/blog-ts-challenge-hero.png',
  'Times Square at night with NFT billboards and XP coins',
  '/og/blog-ts-challenge.png',
  12,
  jsonb_build_array(
    jsonb_build_object(
      'type', 'custom_html',
      'html', $html$<h1 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1.5rem, 1rem + 2vw, 2.5rem);margin-bottom:0.75rem">What is the Times Square Billboard Challenge and how to participate</h1>
<p style="font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-faint);font-style:italic;margin-bottom:2rem">Published: April 2026 | Author: NFT.NYC and OneHub team | Last updated: June 2026</p>
<img src="/blog-ts-challenge-hero.png" alt="Times Square at night with NFT billboards and XP coins" style="width:100%;border-radius:12px;margin-bottom:2rem;border:1px solid var(--card-border)">
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">The Times Square Billboard Challenge (TS Challenge) is a community engagement program on onehub.nft.nyc where collectors, artists, and fans worldwide collect limited-edition digital art from the NFT.NYC 2025 Community Artist Showcase. Participants send Collectible Gifts, earn T-XP (Times Square Experience Points), and compete on a global leaderboard. The platform is powered by OneHub and organized by the NFT.NYC team.</p>
<div style="overflow-x:auto;margin-top:1.5rem"><table style="width:100%;border-collapse:collapse;border:1px solid var(--card-border)"><thead><tr><th style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text);width:30%">Attribute</th><th style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Detail</th></tr></thead><tbody><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Platform</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">onehub.nft.nyc</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Organizer</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">OneHub, built by the NFT.NYC team and powered by NFT.Kred</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Art categories</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Collectible TS Art (curated by Superchief Gallery) and Collectible Gifts</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Display venues</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Times Square billboards, the Monument by Superchief, and the NFT.NYC Community Artists Gallery</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Progression metric</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">T-XP (Times Square Experience Points)</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Cost to join</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Free. Collectible Gifts cost T-XP. Billboard Art is available for collection.</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Community size</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">150,000+ members</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Artists showcased</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">1,500+ from the NFT.NYC 2025 Community Artist Showcase</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Key features</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Collect Art, Send Gifts, Gift Studio, Leaderboard, Dashboard, Daily Actions, Streak System</td></tr></tbody></table></div>
<h2 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1.25rem, 0.8rem + 1.5vw, 1.75rem);margin-bottom:1rem;margin-top:3rem">What is the Times Square Billboard Challenge?</h2>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">The TS Challenge is an interactive, community-driven competition that connects digital collecting with physical display in Times Square, New York City. Participants collect exclusive digital art from the NFT.NYC 2025 Community Artist Showcase, exchange Collectible Gifts with other community members, and accumulate T-XP to rise on a global leaderboard.</p>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7;margin-top:1rem">Every piece of art in the challenge was displayed at physical scale across three venues: Times Square billboards, the Monument by Superchief, and the NFT.NYC Community Artists Gallery. Collecting these works as NFTs on onehub.nft.nyc provides a direct connection to art that appeared in one of the most-visited locations on Earth.</p>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7;margin-top:1rem">The challenge centers on three core actions: <strong style="color:var(--color-text)">collect, earn, and compete</strong>. Every interaction on the platform generates T-XP, which determines leaderboard ranking. Top positions on the leaderboard may unlock future perks and recognition.</p>
<h2 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1.25rem, 0.8rem + 1.5vw, 1.75rem);margin-bottom:1rem;margin-top:3rem">Why the TS Challenge exists</h2>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">NFT.NYC has been the largest gathering of the NFT community since its inception. The Times Square Billboard Challenge extends that community beyond the conference dates and into a year-round engagement layer. The TS Challenge creates a persistent platform where collectors, artists, and fans can connect, exchange gifts, and compete continuously.</p>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7;margin-top:1rem">The challenge also provides a mechanism for artists to reach audiences at unprecedented scale. The NFT.NYC 2025 Community Artist Showcase featured work from over 1,500 artists, and the TS Challenge makes every showcased piece collectible and tradeable through onehub.nft.nyc.</p>
<h2 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1.25rem, 0.8rem + 1.5vw, 1.75rem);margin-bottom:1rem;margin-top:3rem">How the TS Challenge works</h2>
<h3 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1rem, 0.7rem + 1vw, 1.25rem);margin-bottom:0.75rem;margin-top:2rem">Three steps to start competing</h3>
<ol style="padding-left:1.5rem;margin-top:0.5rem">
<li style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7;margin-bottom:0.5rem;padding-left:0.5rem"><strong style="color:var(--color-text)">Collect NFTs.</strong> Connect your wallet and start collecting exclusive TS Art. Each NFT purchased helps support an artist and earns T-XP.</li>
<li style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7;margin-bottom:0.5rem;padding-left:0.5rem"><strong style="color:var(--color-text)">Earn T-XP.</strong> Collect art and send Collectible Gifts to earn T-XP. Completing a Daily Action increases your multiplier.</li>
<li style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7;margin-bottom:0.5rem;padding-left:0.5rem"><strong style="color:var(--color-text)">Climb the ranks.</strong> The more you collect, the higher you climb. All of the T-XP you earn moves you up the leaderboard. Compete with collectors worldwide for the top spot.</li>
</ol>
<h3 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1rem, 0.7rem + 1vw, 1.25rem);margin-bottom:0.75rem;margin-top:2rem">Collectible TS Art</h3>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">This category features limited-edition art from the NFT.NYC 2025 Community Artist Showcase, curated by Superchief Gallery. These are the same pieces that were displayed on Times Square billboards, on the Monument by Superchief, and in the NFT.NYC Community Artists Gallery. Collectible TS Art features subcategories based on display venue: Shown on Billboards, Shown on Monument, and Shown in Art Gallery.</p>
<h3 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1rem, 0.7rem + 1vw, 1.25rem);margin-bottom:0.75rem;margin-top:2rem">Collectible Gifts</h3>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">Collectible Gifts are themed Gifts that can be sent to other community members. Examples include The Botanical Garden Bloom, The Coney Island Spinner, After-Hours Aviators, and The Hudson River Parka. These cost T-XP to send and are central to the social gifting mechanism that drives leaderboard competition.</p>
<div style="overflow-x:auto;margin-top:1rem"><table style="width:100%;border-collapse:collapse;border:1px solid var(--card-border)"><thead><tr><th style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text);width:30%">Category</th><th style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Description</th><th style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text);width:20%">T-XP cost</th></tr></thead><tbody><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Collectible TS Art</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Limited-edition curated art from the NFT.NYC Community Artist Showcase, displayed on billboards and the Monument</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">500 T-XP to 2,500 T-XP and up</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Collectible Gifts</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Themed Gifts for social gifting and community engagement</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">50 to 500 T-XP per gift</td></tr></tbody></table></div>
<h2 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1.25rem, 0.8rem + 1.5vw, 1.75rem);margin-bottom:1rem;margin-top:3rem">How to earn T-XP through engagement</h2>
<h3 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1rem, 0.7rem + 1vw, 1.25rem);margin-bottom:0.75rem;margin-top:2rem">Send gifts</h3>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">Sending Collectible Gifts is one of the primary ways to earn T-XP. Every gift sent and received generates points for both the sender and the recipient. This creates a positive-sum dynamic where generosity directly translates to leaderboard progress.</p>
<h3 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1rem, 0.7rem + 1vw, 1.25rem);margin-bottom:0.75rem;margin-top:2rem">Connect with friends</h3>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">The Community Directory allows participants to discover other collectors. More connections create more opportunities to exchange gifts and accumulate T-XP.</p>
<h3 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1rem, 0.7rem + 1vw, 1.25rem);margin-bottom:0.75rem;margin-top:2rem">Gift Studio</h3>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">The Gift Studio is an AI-enabled creation tool where participants can design custom Collectible Gifts to share with friends. Choose a base design and the AI generates a unique gift. The current base design is Relay, the TS Challenge mascot. Additional base designs may be added over time.</p>
<h2 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1.25rem, 0.8rem + 1.5vw, 1.75rem);margin-bottom:1rem;margin-top:3rem">What is T-XP and how does the points system work?</h2>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">T-XP (Times Square Experience Points) is the off-chain progression metric that powers the entire TS Challenge. It determines leaderboard ranking, unlocks the ability to purchase exclusive TS Art and Collectible Gifts, and tracks overall community engagement. T-XP is earned through platform activity and is displayed in the navigation bar and on your Dashboard. T-XP has no cash value and cannot be redeemed for money. Earned T-XP expires 60 days after issuance; any purchased T-XP expires 12 months after issuance.</p>
<h3 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1rem, 0.7rem + 1vw, 1.25rem);margin-bottom:0.75rem;margin-top:2rem">Daily actions</h3>
<div style="overflow-x:auto;margin-top:0.5rem"><table style="width:100%;border-collapse:collapse;border:1px solid var(--card-border)"><thead><tr><th style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Action</th><th style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text);width:25%">T-XP earned</th></tr></thead><tbody><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Send a gift</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">+10</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Share an NFT on social media</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">+1</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Invite friends to play</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">+1</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Receive a gift</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">+10</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Redeem a benefit</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">+15</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Rank number 1 on leaderboard</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">+500</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Rank number 2 on leaderboard</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">+250</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Rank number 3 on leaderboard</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">+100</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Rank 4 to 10 on leaderboard</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">+10</td></tr></tbody></table></div>
<h3 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1rem, 0.7rem + 1vw, 1.25rem);margin-bottom:0.75rem;margin-top:2rem">Streak system and boost multiplier</h3>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">The Dashboard tracks your daily streak: the number of consecutive days you have completed at least one Daily Action. Maintaining a streak builds your Boost Multiplier, which starts at 1.1x and can increase up to 4x. A higher multiplier means every action you take earns proportionally more T-XP.</p>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7;margin-top:1rem">Breaking your streak resets the multiplier to 1.1x, making consistency a key strategic element for competitive collectors.</p>
<h3 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1rem, 0.7rem + 1vw, 1.25rem);margin-bottom:0.75rem;margin-top:2rem">Progression levels</h3>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">As you accumulate T-XP, you advance through a series of collector levels. Each level unlocks new capabilities and recognition on the platform.</p>
<h2 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1.25rem, 0.8rem + 1.5vw, 1.75rem);margin-bottom:1rem;margin-top:3rem">How the leaderboard works</h2>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">The TS Challenge Leaderboard ranks all participants by their total T-XP score. The leaderboard serves as the central competitive element of the entire challenge, and top positions may unlock future perks.</p>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7;margin-top:1rem">The live leaderboard is always available at <a href="https://onehub.nft.nyc/leaderboard" target="_blank" rel="noopener noreferrer" style="color:var(--color-primary);text-decoration:underline;text-underline-offset:3px">onehub.nft.nyc/leaderboard</a>.</p>
<h2 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1.25rem, 0.8rem + 1.5vw, 1.75rem);margin-bottom:1rem;margin-top:3rem">Platform features on onehub.nft.nyc</h2>
<h3 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1rem, 0.7rem + 1vw, 1.25rem);margin-bottom:0.75rem;margin-top:2rem">Dashboard</h3>
<div style="overflow-x:auto;margin-top:0.5rem"><table style="width:100%;border-collapse:collapse;border:1px solid var(--card-border)"><thead><tr><th style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text);width:25%">Feature</th><th style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Detail</th></tr></thead><tbody><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Overview</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Personal hub showing total T-XP, T-XP earned today, current level, and streak status</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Daily bonus</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Claim once per day to extend your streak and earn bonus T-XP</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Streak tracker</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Displays consecutive-day streak count and current Boost Multiplier (1.1x to 4x)</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Daily actions</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Checklist of earning activities: send and receive gifts, share NFTs, invite friends, redeem benefits, leaderboard rank bonuses</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Recent gifts</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Feed of your latest sent and received gifts with a quick Send More action</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">T-XP transactions</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Full transaction history with running balance</td></tr></tbody></table></div>
<h3 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1rem, 0.7rem + 1vw, 1.25rem);margin-bottom:0.75rem;margin-top:2rem">Collect Art</h3>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">The Collect Art page organizes all available NFTs into two primary categories: Collectible TS Art and Collectible Gifts. Collectible TS Art features subcategories based on display venue: Shown on Billboards, Shown on Monument, and Shown in Art Gallery. Each piece includes the artist name, edition details, and collection options.</p>
<h3 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1rem, 0.7rem + 1vw, 1.25rem);margin-bottom:0.75rem;margin-top:2rem">Send Gifts</h3>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">The Send Gifts page is the gateway to Collectible Gifts. Browse available Collectible Gifts and send them to other community members. Gifting is reciprocal: both sender and recipient earn T-XP for each transaction.</p>
<h3 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1rem, 0.7rem + 1vw, 1.25rem);margin-bottom:0.75rem;margin-top:2rem">Community directory</h3>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">The Community Directory lists all participants, making it easy to discover new collectors, view their collections, and initiate gift exchanges.</p>
<h3 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1rem, 0.7rem + 1vw, 1.25rem);margin-bottom:0.75rem;margin-top:2rem">Activity feed</h3>
<p style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7">The Activity feed shows a real-time stream of all platform activity: gifts sent, NFTs collected, leaderboard movements, and community interactions.</p>
<h2 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1.25rem, 0.8rem + 1.5vw, 1.75rem);margin-bottom:1rem;margin-top:3rem">Who is the TS Challenge for?</h2>
<ol style="padding-left:1.5rem;margin-top:0.5rem">
<li style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7;margin-bottom:0.5rem;padding-left:0.5rem"><strong style="color:var(--color-text)">NFT.NYC attendees and alumni.</strong> If you have attended NFT.NYC before, the TS Challenge is a way to stay engaged with the community year-round.</li>
<li style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7;margin-bottom:0.5rem;padding-left:0.5rem"><strong style="color:var(--color-text)">Digital art collectors.</strong> Collecting curated, limited-edition art from over 1,500 artists, with the added distinction that every piece was physically displayed in Times Square.</li>
<li style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7;margin-bottom:0.5rem;padding-left:0.5rem"><strong style="color:var(--color-text)">NFT enthusiasts and community builders.</strong> The social gifting and leaderboard mechanics make this a community-driven competition where participation is rewarded.</li>
<li style="font-family:var(--font-body);font-size:var(--text-base);color:var(--color-text-muted);line-height:1.7;margin-bottom:0.5rem;padding-left:0.5rem"><strong style="color:var(--color-text)">Newcomers and curious explorers.</strong> The platform is free to join, and the Gift Studio and Daily Actions provide immediate ways to participate.</li>
</ol>
<h2 style="font-family:var(--font-display);font-weight:700;color:var(--color-text);text-transform:uppercase;letter-spacing:-0.02em;font-size:clamp(1.25rem, 0.8rem + 1.5vw, 1.75rem);margin-bottom:1rem;margin-top:3rem">How the TS Challenge compares to other platforms</h2>
<div style="overflow-x:auto;margin-top:0.5rem"><table style="width:100%;border-collapse:collapse;border:1px solid var(--card-border)"><thead><tr><th style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Feature</th><th style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">TS Challenge</th><th style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Traditional NFT marketplace</th><th style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Social media contest</th></tr></thead><tbody><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Curated artist showcase</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Yes</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">No</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">No</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Physical display in Times Square</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Yes</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">No</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">No</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Progression system (T-XP)</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Yes</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">No</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">No</td></tr><tr><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5;font-weight:700;color:var(--color-text)">Global leaderboard</td><td style="padding:0.75rem 1rem;border-bottom:1px solid var(--card-border);font-family:var(--font-body);font-size:var(--text-sm);color:var(--color-text-muted);line-height:1.5">Yes</td><td style="padding:0.75rem 1rem;border